<?php require __DIR__.'/../config/auth.php'; require_role('admin'); require __DIR__.'/../config/database.php';$sales=$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE payment_status='Paid' AND DATE(order_date)=CURDATE()")->fetchColumn();$orders=$pdo->query("SELECT COUNT(*) FROM orders WHERE DATE(order_date)=CURDATE()")->fetchColumn();$low=$pdo->query("SELECT COUNT(*) FROM products WHERE stock<=10")->fetchColumn();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><title>Admin</title></head><body class="admin-body"><header class="admin-header"><div class="brand"><img src="../assets/sea-you-logo.jpg" alt="Sea You logo"><div><b>SEA YOU</b><span>Admin Dashboard</span></div></div><a href="../index.php">← Cashier POS</a></header><div class="page"><div class="page-head"><h1>Restaurant Overview</h1></div><div class="stats"><div><span>Today's Sales</span><b>₱<?=number_format($sales,2)?></b></div><div><span>Today's Orders</span><b><?=$orders?></b></div><div><span>Low Stock</span><b><?=$low?></b></div></div><p>This starter dashboard is connected to the live POS database. Products, users, reports and inventory management can be extended from here.</p></div></body></html>
